boxes=[(21,6),(39,6),(51,27),(56,33),(42,36),(54,42),(23,51),(45,51),(33,45),(33,60)]
def cells(shape,cx,cy):
    s=set()
    for k in range(-14,15):
        if shape=='X': s|={(cx+k,cy+k),(cx+k,cy-k)}
        if shape=='C': s|={(cx+k,cy),(cx,cy+k)}
    if shape=='D':
        for dx in range(-9,10):
            r=9-abs(dx); s|={(cx+dx,cy+r),(cx+dx,cy-r)}
    return s
def cov(s):
    return frozenset(i for i,(bx,by) in enumerate(boxes) if any((bx+a,by+b) in s for a in(-1,0,1) for b in(-1,0,1)))
pos=[(x,y) for x in range(0,64,3) for y in range(0,64,3)]
C={sh:{} for sh in 'XCD'}
for sh in 'XCD':
    for p in pos:
        C[sh].setdefault(cov(cells(sh,*p)),p)
full=frozenset(range(10)); sols=[]
for a,pa in C['X'].items():
    for b,pb in C['C'].items():
        if len(a|b)<4: continue
        for d,pd in C['D'].items():
            if a|b|d==full: sols.append((pa,pb,pd))
print(len(sols),sols[:10])
